+const { useState, useId, useRef } = React;
+
+const QUESTIONS = [
+  {
+    id: "q1",
+    prompt: "Which of these are statically typed languages?",
+    help: "Select all that apply. Statically typed languages check types at compile time.",
+    options: [
+      { value: "java", label: "Java" },
+      { value: "python", label: "Python" },
+      { value: "typescript", label: "TypeScript" },
+      { value: "javascript", label: "JavaScript" },
+    ],
+    correct: ["java", "typescript"],
+  },
+  {
+    id: "q2",
+    prompt: "Which of these languages run on the JVM?",
+    options: [
+      { value: "kotlin", label: "Kotlin" },
+      { value: "scala", label: "Scala" },
+      { value: "rust", label: "Rust" },
+      { value: "go", label: "Go" },
+    ],
+    correct: ["kotlin", "scala"],
+  },
+  {
+    id: "q3",
+    prompt: "Which languages are commonly used for systems programming?",
+    options: [
+      { value: "c", label: "C" },
+      { value: "rust", label: "Rust" },
+      { value: "ruby", label: "Ruby" },
+      { value: "php", label: "PHP" },
+    ],
+    correct: ["c", "rust"],
+  },
+];
+
+function CheckboxQuestion({ question, selected, onToggle }) {
+  const helpId = question.help ? `${question.id}-help` : undefined;
+  return (
+    <fieldset className="form-field" aria-describedby={helpId}>
+      <legend>{question.prompt}</legend>
+      {question.help && (
+        <p id={helpId} className="help-text">{question.help}</p>
+      )}
+      <div className="options">
+        {question.options.map((opt) => {
+          const inputId = `${question.id}-${opt.value}`;
+          const checked = selected.includes(opt.value);
+          return (
+            <label key={opt.value} className="option" htmlFor={inputId}>
+              <input
+                id={inputId}
+                type="checkbox"
+                name={question.id}
+                value={opt.value}
+                checked={checked}
+                onChange={() => onToggle(question.id, opt.value)}
+              />
+              <span className="option-label">{opt.label}</span>
+            </label>
+          );
+        })}
+      </div>
+    </fieldset>
+  );
+}
+
+function Quiz() {
+  const [answers, setAnswers] = useState(
+    Object.fromEntries(QUESTIONS.map((q) => [q.id, []]))
+  );
+  const [result, setResult] = useState(null);
+  const resultRef = useRef(null);
+
+  const toggle = (qId, value) => {
+    setAnswers((prev) => {
+      const cur = prev[qId];
+      const next = cur.includes(value)
+        ? cur.filter((v) => v !== value)
+        : [...cur, value];
+      return { ...prev, [qId]: next };
+    });
+  };
+
+  const handleSubmit = (e) => {
+    e.preventDefault();
+    let score = 0;
+    const breakdown = QUESTIONS.map((q) => {
+      const sel = [...answers[q.id]].sort();
+      const correct = [...q.correct].sort();
+      const isCorrect =
+        sel.length === correct.length &&
+        sel.every((v, i) => v === correct[i]);
+      if (isCorrect) score += 1;
+      return { id: q.id, prompt: q.prompt, isCorrect };
+    });
+    setResult({ score, total: QUESTIONS.length, breakdown });
+    setTimeout(() => {
+      if (resultRef.current) resultRef.current.focus();
+    }, 0);
+  };
+
+  return (
+    <form noValidate onSubmit={handleSubmit}>
+      {QUESTIONS.map((q) => (
+        <CheckboxQuestion
+          key={q.id}
+          question={q}
+          selected={answers[q.id]}
+          onToggle={toggle}
+        />
+      ))}
+
+      <div className="actions">
+        <button type="submit">Submit answers</button>
+      </div>
+
+      {result && (
+        <div
+          className="result"
+          role="status"
+          aria-live="polite"
+          tabIndex={-1}
+          ref={resultRef}
+        >
+          <h2>You scored {result.score} of {result.total}</h2>
+          <ul>
+            {result.breakdown.map((b) => (
+              <li key={b.id}>
+                {b.prompt} — {b.isCorrect ? "Correct" : "Incorrect"}
+              </li>
+            ))}
+          </ul>
+        </div>
+      )}
+    </form>
+  );
+}
+
+ReactDOM.createRoot(document.getElementById("root")).render(<Quiz />);
+
